insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Com a finalidade de atender pessoas com necessidades complexas de comunicação, o poder público instalará, em praças, parques e demais espaços públicos de uso coletivo, placas com sistemas de comunicação aumentativa e alternativa, compostas de pranchas de baixa tecnologia com pictogramas. As placas deverão ser adaptadas aos contextos comunicativos e confeccionadas em materiais resistentes às condições climáticas.', '["Placas de comunicação aumentativa e alternativa em espaços públicos.","Pictogramas e materiais resistentes."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'A praça tem placas com pictogramas para facilitar a comunicação.', '["Assertiva que restringe essas placas a hospitais erra: são para espaços públicos de uso coletivo."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-62-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '88979eaba7c2a6a71f512a5d8bd832643b8b2108992c3c0b45348bf4143fb53f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É obrigatória a acessibilidade nos sítios da internet mantidos por empresas com sede ou representação comercial no País ou por órgãos de governo, para uso da pessoa com deficiência, conforme as melhores práticas e diretrizes internacionais. Os sítios devem conter símbolo de acessibilidade em destaque. Telecentros comunitários que recebam recursos públicos federais e lan houses devem possuir equipamentos e instalações acessíveis, garantindo, no mínimo, 10% de seus computadores com recursos de acessibilidade para pessoa com deficiência visual, com pelo menos 1 equipamento.', '["Acessibilidade obrigatória nos sítios de empresas e do governo.","Símbolo de acessibilidade em destaque.","Telecentros e lan houses: no mínimo 10% dos computadores acessíveis."]'::jsonb, '["Mínimo de 10% dos computadores, e pelo menos 1."]'::jsonb, 'A loja virtual precisa ser compatível com leitores de tela.', '["Assertiva que isenta empresas privadas da acessibilidade de seus sítios erra."]'::jsonb, '[]'::jsonb, '["Art. 64"]'::jsonb, 'under_review', 'claude'
