insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público deve adotar mecanismos de incentivo à produção, edição, difusão, distribuição e comercialização de livros em formatos acessíveis, inclusive em publicações da administração pública ou financiadas com recursos públicos. Nos editais de compras de livros, o poder público deverá adotar cláusulas de impedimento à participação de editoras que não ofertem sua produção também em formatos acessíveis. Consideram-se formatos acessíveis os arquivos digitais reconhecidos por leitores de tela ou outras tecnologias assistivas, permitindo leitura com voz sintetizada, ampliação de caracteres, contrastes e impressão em Braille. Deve-se estimular a adaptação de artigos científicos em formato acessível, inclusive em Libras.', '["Incentivo a livros em formatos acessíveis.","Editais impedem editoras que não ofertem formato acessível.","Conceito de formato acessível.","Artigos científicos em formato acessível e Libras."]'::jsonb, '["Editoras sem formato acessível são impedidas de participar de compras públicas de livros."]'::jsonb, 'A editora só vende livros ao governo se oferecer também versões acessíveis.', '["Assertiva que permite a compra pública de livros apenas em formato impresso comum erra."]'::jsonb, '[]'::jsonb, '["Art. 42"]'::jsonb, 'under_review', 'claude'
