insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público deve assegurar a disponibilidade de informações corretas e claras sobre os diferentes produtos e serviços, por quaisquer meios, inclusive virtual, com a especificação de quantidade, qualidade, características, composição e preço, bem como sobre os eventuais riscos à saúde e à segurança do consumidor com deficiência. Os canais de comercialização virtual e os anúncios devem disponibilizar os recursos de acessibilidade do art. 67, a expensas do fornecedor. Os fornecedores devem disponibilizar, mediante solicitação, bulas, prospectos e materiais de divulgação em formato acessível.', '["Informações claras e acessíveis sobre produtos e serviços.","Recursos de acessibilidade nos anúncios, a expensas do fornecedor.","Bulas e materiais em formato acessível, mediante solicitação."]'::jsonb, '["Custeio dos recursos de acessibilidade pelo FORNECEDOR."]'::jsonb, 'O laboratório fornece a bula em formato acessível, quando solicitado.', '["Assertiva que transfere ao consumidor o custo dos recursos de acessibilidade na publicidade erra."]'::jsonb, '[]'::jsonb, '["Art. 67"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-69' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c16888743293ad9876d0130228210d6160441373c7142afccffb9e80d4fa77b2'
