insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Lei nº 9.029, de 13 de abril de 1995, passa a vigorar com alterações: é proibida a adoção de qualquer prática discriminatória e limitativa para efeito de acesso à relação de trabalho ou de sua manutenção, por motivo de sexo, origem, raça, cor, estado civil, situação familiar, deficiência, reabilitação profissional, idade, entre outros; as infrações são passíveis de cominações, inclusive a reintegração com ressarcimento integral de todo o período de afastamento, mediante pagamento das remunerações devidas, corrigidas monetariamente e acrescidas de juros legais.', '["Proibida a discriminação no acesso e na manutenção do emprego, inclusive por deficiência.","Reintegração com ressarcimento integral."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei nº 9.029, de 1995.","Reintegração com ressarcimento integral."]'::jsonb, 'O empregado dispensado por discriminação é reintegrado e recebe os salários do período.', '["Assertiva que impede a reintegração do empregado dispensado por deficiência erra."]'::jsonb, '[]'::jsonb, '["Art. 34"]'::jsonb, 'under_review', 'claude'
