insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 35 da Lei nº 9.250, de 26 de dezembro de 1995, passa a vigorar acrescido do §5º: a pessoa com deficiência, ou o contribuinte que tenha dependente nessa condição, tem preferência na restituição do imposto de renda, sem prejuízo da preferência dos idosos.', '["Preferência na restituição do imposto de renda."]'::jsonb, '["ATUALIZAÇÃO: altera a lei do imposto de renda."]'::jsonb, 'A pessoa com deficiência recebe a restituição do imposto de renda com prioridade.', '["Assertiva que nega a preferência na restituição à pessoa com deficiência erra."]'::jsonb, '[]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
