insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 1º da Lei nº 10.048, de 8 de novembro de 2000, passa a prever que as pessoas com deficiência, os idosos com idade igual ou superior a 60 anos, as gestantes, as lactantes, as pessoas com crianças de colo e os obesos terão atendimento prioritário.', '["Atendimento prioritário: pessoas com deficiência, idosos, gestantes, lactantes, pessoas com crianças de colo e obesos."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei de Atendimento Prioritário; inclui os obesos."]'::jsonb, 'A lactante e o obeso também têm atendimento prioritário.', '["Assertiva que exclui os obesos do atendimento prioritário erra."]'::jsonb, '[]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-111' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a99e2a5b7b2c4d0bf44091de8616bdbdd7c9ccc0c9f424908695e33f28b6123b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
