insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Código Civil passa a vigorar com alterações: são absolutamente incapazes apenas os menores de 16 anos; são relativamente incapazes, entre outros, os ébrios habituais, os viciados em tóxico e aqueles que, por causa transitória ou permanente, não puderem exprimir sua vontade; a pessoa com deficiência poderá testemunhar em igualdade de condições, com recursos de tecnologia assistiva; os pais ou tutores podem revogar a autorização até a celebração do casamento; e a pessoa com deficiência mental ou intelectual em idade núbil poderá contrair matrimônio, expressando sua vontade diretamente ou por meio de seu responsável ou curador.', '["Absolutamente incapazes: só os menores de 16 anos.","Pessoa com deficiência pode testemunhar.","Pessoa com deficiência pode casar."]'::jsonb, '["ATUALIZAÇÃO: altera o Código Civil (arts. 3º, 4º, 228, 1.518, 1.548, 1.550, 1.557).","A deficiência NÃO gera mais incapacidade absoluta."]'::jsonb, 'A pessoa com deficiência intelectual pode se casar.', '["Assertiva que mantém a pessoa com deficiência mental como absolutamente incapaz erra: só os menores de 16 anos são absolutamente incapazes."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-114' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '98736a4c37117e8432f88998ee1116470a5f423fe092c2c109ee3c1d8c713106'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Título IV do Livro IV da Parte Especial do Código Civil passa a ter a redação: Da Tutela, da Curatela e da Tomada de Decisão Apoiada.', '["Novo título: tutela, curatela e tomada de decisão apoiada."]'::jsonb, '["ATUALIZAÇÃO: altera a nomenclatura do Título IV do Código Civil."]'::jsonb, 'O Código Civil agora trata da tomada de decisão apoiada no mesmo título da curatela.', '["Assertiva que não prevê a tomada de decisão apoiada no Código Civil erra."]'::jsonb, '[]'::jsonb, '["Art. 116"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-115' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'aa1deeba27c7cee06b6b682d5e9c119f146384ecc38f507098074afbe05b1f6e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Código Civil passa a ter o Capítulo III, da Tomada de Decisão Apoiada. Ela é o processo pelo qual a pessoa com deficiência elege pelo menos 2 pessoas idôneas, com as quais mantenha vínculos e que gozem de sua confiança, para prestar-lhe apoio na tomada de decisão sobre atos da vida civil, fornecendo-lhes os elementos e informações necessários. Para o pedido, a pessoa e os apoiadores apresentam termo com os limites do apoio e os compromissos, inclusive o prazo de vigência. O pedido é requerido pela pessoa apoiada, com indicação dos apoiadores. Antes de decidir, o juiz, assistido por equipe multidisciplinar e ouvido o Ministério Público, ouve pessoalmente o requerente e os apoiadores.', '["Tomada de decisão apoiada.","Pelo menos 2 apoiadores idôneos.","Termo com limites do apoio e prazo de vigência.","Pedido pela própria pessoa apoiada.","Juiz ouve pessoalmente os envolvidos, com equipe multidisciplinar e MP."]'::jsonb, '["Mínimo de 2 apoiadores.","O pedido é da PRÓPRIA pessoa apoiada, e ela mantém sua capacidade."]'::jsonb, 'A pessoa escolhe dois amigos de confiança para apoiá-la nos contratos que fizer.', '["Assertiva que permite a tomada de decisão apoiada com um único apoiador erra: são pelo menos 2."]'::jsonb, '[{"termo":"Tomada de decisão apoiada","significado":"Apoio escolhido pela pessoa com deficiência para decidir, sem perder a capacidade."}]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-116' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c0fa85cff8e39b3043e61ca042a1bf0d5b29ac93ff2f179b8832956430d61466'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
