insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Comissão Técnica de Classificação, existente em cada estabelecimento, será presidida pelo Diretor e composta, no mínimo, por dois chefes de serviço, um psiquiatra, um psicólogo e um assistente social, quando se tratar de condenado à pena privativa de liberdade. Nos demais casos, atuará junto ao Juízo da Execução e será integrada por fiscais do Serviço Social.', '["Presidida pelo Diretor.","Dois chefes de serviço, um psiquiatra, um psicólogo e um assistente social.","Demais casos: junto ao Juízo da Execução, com fiscais do Serviço Social."]'::jsonb, '["Composição mínima: dois chefes de serviço, psiquiatra, psicólogo e assistente social."]'::jsonb, 'O diretor preside a Comissão composta por psicólogo, psiquiatra e assistente social.', '["Assertiva que dispensa psiquiatra e psicólogo na Comissão erra."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-7' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'fc2b7903a1a1ddf006e5b4755f0daf5fec30c7887c9819b26aa154f2372f0039'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condenado ao cumprimento de pena privativa de liberdade, em regime fechado, será submetido a exame criminológico para a obtenção dos elementos necessários a uma adequada classificação e com vistas à individualização da execução. Ao exame poderá ser submetido o condenado em regime semiaberto.', '["Exame criminológico obrigatório no regime fechado.","Facultativo no semiaberto."]'::jsonb, '["Obrigatório no FECHADO; facultativo no SEMIABERTO."]'::jsonb, 'O condenado em regime fechado é submetido ao exame criminológico no início da pena.', '["Assertiva que torna obrigatório o exame criminológico no regime semiaberto erra: é facultativo."]'::jsonb, '[{"termo":"Exame criminológico","significado":"Avaliação técnica da personalidade e da periculosidade do condenado."}]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-8' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c5fb465b96d7c34ee0df70d40b149ad1a96ae06c05d97e454116992d55a6ffa3'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
